    function hexToRgb(hex) {
      let clean = hex.replace('#', '');
      if (clean.length === 3) {
        clean = clean
          .split('')
          .map((c) => c + c)
          .join('');
      }
      const num = parseInt(clean, 16);
      return isNaN(num)
        ? null
        : {
            r: (num >> 16) & 255,
            g: (num >> 8) & 255,
            b: num & 255,
          };
    }

    function getLuminance(r, g, b) {
      const a = [r, g, b].map((v) => {
        v /= 255;
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
